def bfsLevelSizes(n, edges, src):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    seen = [False] * n
    seen[src] = True
    level = [src]
    sizes = []
    while level:
        sizes.append(len(level))
        nxt = []
        for u in level:
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    nxt.append(v)
        level = nxt
    return sizes
